function enmascararNumeros(texto) {
  return String(texto ?? '').replace(/\d{6,}/g, d => d.slice(0, 3) + '***' + d.slice(-4));
}
function armarAlertaError(ev, repetidasAntes, fechaTexto) {
  const ex = ev?.execution ?? {}, tr = ev?.trigger ?? {};
  const wf = ev?.workflow?.name ?? ex.workflow?.name ?? '(workflow desconocido)';
  const wfId = ev?.workflow?.id ?? ex.workflow?.id ?? '';
  const nodo = ex.error?.node?.name ?? ex.lastNodeExecuted ?? tr.error?.node?.name ?? '(nodo desconocido)';
  let msg = enmascararNumeros(ex.error?.message ?? tr.error?.message ?? 'sin mensaje');
  if (msg.length > 500) msg = msg.slice(0, 497) + '...';
  const lineas = ['[Error] ' + wf, 'Nodo: ' + nodo, 'Hora: ' + fechaTexto, 'Error: ' + msg];
  if (ex.id) lineas.push('Ejecución: ' + ex.id);
  if (Number(repetidasAntes) > 0) lineas.push('(se repitió ' + repetidasAntes + ' veces en los últimos minutos sin aviso)');
  return { clave: wfId + ':' + nodo, texto: lineas.join('\n') };
}
const fecha=new Intl.DateTimeFormat('es-CO',{timeZone:'America/Bogota',dateStyle:'short',timeStyle:'medium'}).format(new Date());
return [{json:armarAlertaError($json,0,fecha)}];

